return ['messages'=>['0e747ff8b1ac4477d92045e85c49b1be'=>'Jimmy Solano, <em>Commercial Head</em> of Centroamérica.','14dee4ddd3a44872d05b1c4e85609379'=>'<span class="TextRun SCXW264565588 BCX0" lang="EN-US" xml:lang="EN-US" data-contrast="none"><span class="NormalTextRun SCXW264565588 BCX0">With a strong </span><span class="NormalTextRun SCXW264565588 BCX0">track record</span><span class="NormalTextRun SCXW264565588 BCX0"> of commitment to local development, </span><a href="https://www.coopesanramon.fi.cr/" target="_blank" rel="noopener"><span class="NormalTextRun SpellingErrorV2Themed SCXW264565588 BCX0">Coopesanramón</span></a><span class="NormalTextRun SCXW264565588 BCX0"> joins the financial institutions that are transforming their members’ experience through accessible and sustainable digital solutions.</span></span><span class="EOP SCXW264565588 BCX0" data-ccp-props="{&quot;335551550&quot;:6,&quot;335551620&quot;:6}"> </span>','2e804d96f7b939d21bb11946a47e30c5'=>'We congratulate Coopesanramón on this important achievement and for continuing to implement initiatives that transform their members’ experience and strengthen their position in the financial market. ','6392ee3a9e9b8f91a9416880fa2a20f8'=>'For Evertec, Zunify is a key platform to strengthen the payment ecosystem in Costa Rica, driving transactions in businesses and offering users multiple benefits. Being Coopesanramón’s technology partner in this project allows us to fulfill our commitment to provide solutions that evolve with market needs, supporting its mission of offering reliable services through cutting-edge technology that enables fast, secure, and enhanced	 transactions.','Con una sólida trayectoria de compromiso con el desarrollo local, <a href="https://www.coopesanramon.fi.cr/" target="_blank" rel="noreferrer noopener">Coopesanramón</a> se suma a las entidades financieras que están transformando la experiencia de sus asociados mediante soluciones digitales accesibles y sostenibles. '=>'<span class="TextRun SCXW264565588 BCX0" lang="EN-US" xml:lang="EN-US" data-contrast="none"><span class="NormalTextRun SCXW264565588 BCX0">With a strong </span><span class="NormalTextRun SCXW264565588 BCX0">track record</span><span class="NormalTextRun SCXW264565588 BCX0"> of commitment to local development, </span><a href="https://www.coopesanramon.fi.cr/" target="_blank" rel="noopener"><span class="NormalTextRun SpellingErrorV2Themed SCXW264565588 BCX0">Coopesanramón</span></a><span class="NormalTextRun SCXW264565588 BCX0"> joins the financial institutions that are transforming their members’ experience through accessible and sustainable digital solutions.</span></span><span class="EOP SCXW264565588 BCX0" data-ccp-props="{&quot;335551550&quot;:6,&quot;335551620&quot;:6}"> </span>','Felicitamos a Coopesanramón por este importante logro y por seguir implementando iniciativas que transforman la experiencia de sus asociados y fortalecen su posición en el mercado financiero. '=>'We congratulate Coopesanramón on this important achievement and for continuing to implement initiatives that transform their members’ experience and strengthen their position in the financial market. ','Jimmy Solano, <em>Commercial Head</em> de Centroamérica.'=>'Jimmy Solano, <em>Commercial Head</em> of Centroamérica.','La cooperativa ha dado un paso clave en su evolución tecnológica al implementar Zunify, la red de <a href="/solucion/pagos-con-billetera-digital-y-codigo-qr/">pagos QR de Evertec</a> que unifica el sistema financiero en una sola aplicación. Esta innovación les permite a los clientes de la cooperativa centralizar la gestión de sus cuentas de débito, realizar pagos con códigos QR, acumular <em>cashback</em>, aplicar descuentos y promociones en comercios afiliados, y realizar pagos remotos mediante la funcionalidad Notify.'=>'<span class="TextRun SCXW230488240 BCX0" lang="EN-US" xml:lang="EN-US" data-contrast="none"><span class="NormalTextRun SCXW230488240 BCX0">The cooperative has taken a key step in its technological evolution by implementing </span><span class="NormalTextRun SpellingErrorV2Themed SCXW230488240 BCX0">Zunify</span><span class="NormalTextRun SCXW230488240 BCX0">, Evertec’s QR payment network that unifies the financial system in a single application. This innovation allows the cooperative’s clients to centralize the management of their debit accounts, make <a href="https://evertecinc-com.plataformasegura.nubity.com/en/solution/digital-wallet-and-qr-code-payments/" target="_blank" rel="noopener">QR code payments</a>, accumulate cashback, apply discounts and promotions in affiliated stores, and make remote payments through </span><span class="NormalTextRun SCXW230488240 BCX0">the Notify</span><span class="NormalTextRun SCXW230488240 BCX0"> functionality.</span></span><span class="EOP SCXW230488240 BCX0" data-ccp-props="{&quot;335551550&quot;:6,&quot;335551620&quot;:6}"> </span>','Para Evertec, Zunify es una plataforma clave para fortalecer el ecosistema de pagos en Costa Rica, impulsando las transacciones en comercios y ofreciendo a los usuarios múltiples beneficios. Ser el socio tecnológico de Coopesanramón en este proyecto nos permite cumplir nuestro compromiso de brindar soluciones que evolucionen con las necesidades del mercado, apoyando su misión de ofrecer servicios confiables mediante tecnología de vanguardia que facilita transacciones rápidas, seguras y con valor agregado. '=>'For Evertec, Zunify is a key platform to strengthen the payment ecosystem in Costa Rica, driving transactions in businesses and offering users multiple benefits. Being Coopesanramón’s technology partner in this project allows us to fulfill our commitment to provide solutions that evolve with market needs, supporting its mission of offering reliable services through cutting-edge technology that enables fast, secure, and enhanced	 transactions.','df573ef0462c63990f6e7fc1d68f836e'=>'<span class="TextRun SCXW230488240 BCX0" lang="EN-US" xml:lang="EN-US" data-contrast="none"><span class="NormalTextRun SCXW230488240 BCX0">The cooperative has taken a key step in its technological evolution by implementing </span><span class="NormalTextRun SpellingErrorV2Themed SCXW230488240 BCX0">Zunify</span><span class="NormalTextRun SCXW230488240 BCX0">, Evertec’s QR payment network that unifies the financial system in a single application. This innovation allows the cooperative’s clients to centralize the management of their debit accounts, make <a href="https://evertecinc-com.plataformasegura.nubity.com/en/solution/digital-wallet-and-qr-code-payments/" target="_blank" rel="noopener">QR code payments</a>, accumulate cashback, apply discounts and promotions in affiliated stores, and make remote payments through </span><span class="NormalTextRun SCXW230488240 BCX0">the Notify</span><span class="NormalTextRun SCXW230488240 BCX0"> functionality.</span></span><span class="EOP SCXW230488240 BCX0" data-ccp-props="{&quot;335551550&quot;:6,&quot;335551620&quot;:6}"> </span>']];
